def comps(mask):
 seen=set(); result=[]
 for r,c in zip(*np.where(mask)):
  p=(int(r),int(c))
  if p in seen: continue
  q=[p];seen.add(p); comp=[]
  while q:
   x,y=q.pop();comp.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(x+dx,y+dy)
    if 0<=z[0]<16 and 0<=z[1]<16 and mask[z] and z not in seen:seen.add(z);q.append(z)
  result.append(comp)
 return result
